def _normalize(path):
    if "?" in path or "#" in path:
        raise ValueError("queries and fragments are forbidden")
    parts = [part for part in path.split("/") if part]
    if any(part in (".", "..") for part in parts):
        raise ValueError("relative segments are forbidden")
    return "/" if not parts else "/" + "/".join(parts) + "/"


def compile_routes(specs):
    if isinstance(specs, (str, bytes)):
        raise TypeError("specs must be an iterable")
    try:
        items = list(specs)
    except TypeError:
        raise TypeError("specs must be an iterable") from None
    result = []
    seen = set()
    for item in items:
        if isinstance(item, (str, bytes)):
            raise TypeError("route must be a two-element sequence")
        try:
            pair = list(item)
        except TypeError:
            raise TypeError("route must be a two-element sequence") from None
        if len(pair) != 2:
            raise TypeError("route must contain two fields")
        path, handler = pair
        if not isinstance(path, str) or not isinstance(handler, str):
            raise TypeError("route fields must be strings")
        if not handler:
            raise ValueError("handler must be non-empty")
        normalized = _normalize(path)
        if path in seen:
            raise ValueError("duplicate path")
        seen.add(path)
        result.append((normalized, handler))
    return tuple(result)

